use crate::Polyline;
use crate::Point;
use crate::Vector;
use crate::Color;

// Constructor with points
let p0 = Point::new(0.0, 0.0, 0.0);
let p1 = Point::new(1.0, 0.0, 0.0);
let p2 = Point::new(1.0, 1.0, 0.0);
let mut pl = Polyline::new(vec![p0, p1, p2]);

// Basic properties
let point_count = pl.len();
let segment_count = pl.segment_count();
let is_empty = pl.is_empty();

// Get point (read values before mutating)
let pt = pl.get_point(1).unwrap().clone();

// Add point
pl.add_point(Point::new(0.0, 1.0, 0.0));
let new_count = pl.len();

// String representation
let plstr = pl.to_string();

// Translation operators
let pl2 = Polyline::new(vec![Point::new(0.0, 0.0, 0.0), Point::new(1.0, 0.0, 0.0)]);
let v = Vector::new(1.0, 1.0, 1.0);
let pl_add = pl2.clone() + &v;
let pl_sub = pl2 - &v;

// Polyline with custom color and width
let mut plc = Polyline::new(vec![Point::new(0.0, 0.0, 0.0), Point::new(1.0, 0.0, 0.0)]);
plc.linecolor = Color::with_name(255, 0, 0, 255, "red");
